  b: { bold: true },
  strong: { bold: true },
  i: { italic: true },
  em: { italic: true },
  cite: { italic: true },
  dfn: { italic: true },
  var: { italic: true },
  u: { underline: true },
  ins: { underline: true },
  s: { strikethrough: true },
  del: { strikethrough: true },
  strike: { strikethrough: true },
  code: { code: true },
  tt: { code: true },
  samp: { code: true },
  kbd: { key: true },
  mark: { mark: true },
  small: { dim: true },
  sub: { sub: true },
  sup: { sup: true },
